package com.reps.demogcloud.services.trackedBehavior;
import com.reps.demogcloud.data.*;
import com.reps.demogcloud.models.student.Student;
import com.reps.demogcloud.models.trackedBehavior.*;
import com.reps.demogcloud.services.*;
import org.junit.jupiter.api.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.mockito.ArgumentMatchers.*;
import java.util.*;
class TrackedBehaviorServiceImplTest {
    TrackedBehaviorEventRepository records;WorkflowAccessService access;UserContextService users;StudentRepository students;TrackedBehaviorServiceImpl service;
    @BeforeEach void setup(){records=mock(TrackedBehaviorEventRepository.class);access=mock(WorkflowAccessService.class);users=mock(UserContextService.class);students=mock(StudentRepository.class);service=new TrackedBehaviorServiceImpl(records,access,users,students);when(users.getCurrentStaffEmail()).thenReturn("teacher@example.test");when(users.getCurrentUserSchool()).thenReturn("Testing");when(access.sameSchool("Testing")).thenReturn(true);when(students.findByStudentEmailIgnoreCase(anyString())).thenAnswer(i->{var s=new Student();s.setStudentEmail(i.getArgument(0));s.setSchool("Testing");return s;});when(records.saveAll(anyList())).thenAnswer(i->i.getArgument(0));}
    TrackedBehaviorRequest request(String email){var r=new TrackedBehaviorRequest();r.setStudentEmail(email);r.setBehaviorCode("PHONE_OUT");r.setConsequenceCode("WARNING");return r;}
    @Test void batchesCannotSilentlySkipMalformedItems(){assertThrows(IllegalArgumentException.class,()->service.saveTrackedBehaviorEvents(null));assertThrows(IllegalArgumentException.class,()->service.saveTrackedBehaviorEvents(List.of()));assertThrows(IllegalArgumentException.class,()->service.saveTrackedBehaviorEvents(Arrays.asList(request("child@example.test"),null)));verify(records,never()).saveAll(anyList());}
    @Test void invalidBehaviorAndConsequenceRejectEntireBatchBeforeWrites(){for(String code:List.of("INVALID","PHONE_OUT")){var invalid=request("other@example.test");invalid.setBehaviorCode(code);invalid.setConsequenceCode("INVALID");assertThrows(IllegalArgumentException.class,()->service.saveTrackedBehaviorEvents(List.of(request("child@example.test"),invalid)));}verify(records,never()).saveAll(anyList());}
    @Test void actorSchoolAndNamesAreCanonicalAndBatchTimestampShared(){var a=request("child@example.test");a.setConsequenceName("Forged");var result=service.saveTrackedBehaviorEvents(List.of(a,request("other@example.test")));assertEquals(2,result.size());assertEquals(result.get(0).getTimeCreated(),result.get(1).getTimeCreated());assertEquals("teacher@example.test",result.get(0).getTeacherEmail());assertEquals("Testing",result.get(0).getSchool());assertEquals("Warning",result.get(0).getConsequenceName());assertEquals("Phone Out",result.get(0).getBehaviorName());}
    @Test void historyAndTotalsExcludeSchoollessForeignAndUnrequestedLegacyEvents(){var own=TrackedBehaviorEvent.builder().studentEmail("child@example.test").school("Testing").behaviorCode("PHONE_OUT").build();var foreign=TrackedBehaviorEvent.builder().studentEmail("child@example.test").school("Other").behaviorCode("PHONE_OUT").build();var noSchool=TrackedBehaviorEvent.builder().studentEmail("child@example.test").behaviorCode("PHONE_OUT").build();var unrelated=TrackedBehaviorEvent.builder().studentEmail("other@example.test").school("Testing").behaviorCode("PHONE_OUT").build();when(records.findByStudentEmailOrderByTimeCreatedDesc("child@example.test")).thenReturn(List.of(own,foreign,noSchool,unrelated));assertEquals(List.of(own),service.getStudentTrackedBehaviorTimeline("child@example.test"));assertEquals(Map.of("PHONE_OUT",1),service.getStudentTrackedBehaviorTotals("child@example.test"));}
    @Test void totalsUsePersistedSchoolAndValidateEveryStudentBeforeLookup(){var request=new TrackedBehaviorStudentTotalsRequest();request.setStudentEmails(List.of("child@example.test","other@example.test"));when(records.findBySchoolAndStudentEmailInOrderByTimeCreatedDesc("Testing",request.getStudentEmails())).thenReturn(List.of());assertEquals(2,service.getTrackedBehaviorTotalsForStudents(request).size());verify(access).requireStudentAccess("child@example.test");verify(access).requireStudentAccess("other@example.test");verify(records).findBySchoolAndStudentEmailInOrderByTimeCreatedDesc("Testing",request.getStudentEmails());}
    @Test void deniedStudentInBatchNeverWrites(){doThrow(new org.springframework.security.access.AccessDeniedException("denied")).when(access).requireStudentAccess("other@example.test");assertThrows(org.springframework.security.access.AccessDeniedException.class,()->service.saveTrackedBehaviorEvents(List.of(request("child@example.test"),request("other@example.test"))));verify(records,never()).saveAll(anyList());}
    @Test void typesRemainCanonicalForAuthorizedActors(){assertEquals(TrackedBehaviorType.getAll().size(),service.getTrackedBehaviorTypes().size());verify(access).requireStaff();}
    @Test void duplicateEventsInSameBatchCannotWriteHistory(){var input=request("child@example.test");assertThrows(IllegalArgumentException.class,()->service.saveTrackedBehaviorEvents(List.of(input,input)));verify(records,never()).saveAll(anyList());}

}
